import * as React from "react"
import SaveToAccount, { useOpenSaved } from "../account/SaveToAccount"
import {
  CORNER_DOTS,
  CORNER_SQUARES,
  DESTINATIONS,
  FORMATS,
  LEVELS,
  PATTERNS,
  SWATCHES,
  emptyQr,
  encodeValue,
  qrFilename,
  qrOptions,
  qrProblem,
} from "../../lib/qr"
import { readImageFile } from "../../lib/read-image"
import * as s from "./Qr.module.css"

/**
 * The QR code studio — MTC-FCS-020.
 * ============================================================================
 * Ported from the qrcode-king prototype. Everything about analytics,
 * campaigns, dashboards and saved codes was left behind; what is here is the
 * part that makes a code and hands it over.
 *
 * ── THE LIBRARY IS LOADED IN THE BROWSER, NOT AT MODULE SCOPE ──────────────
 * `qr-code-styling` reaches for `document` as soon as it is constructed, and
 * Gatsby renders every page on a server first. The prototype could construct
 * one at the top of the file because Vite only ever ran it in a browser; here
 * that is a build failure, so it is imported inside an effect.
 *
 * ── NOTHING IS UPLOADED ────────────────────────────────────────────────────
 * The code is generated in this tab and downloaded from it. No account, no
 * request, and a logo picked here never leaves the browser — which is also why
 * there is nothing to promise about what happens to it.
 *
 * ── AN EMPTY CODE IS NOT DOWNLOADABLE ──────────────────────────────────────
 * The preview shows a placeholder so the styling controls do something, but
 * Download stays disabled until there is a real destination. A QR code
 * somebody prints on a van and later discovers points at nothing is the one
 * failure this page can actually cause.
 */
/* Defined out here, not inside QrStudio — MTC-FCS-020.
   A component declared in a render body is a NEW component type every render,
   so React unmounts and remounts the whole subtree on every keystroke. The
   destination input lost its DOM node (and its focus) after the first
   character, which presents as "typing does not work" rather than as anything
   to do with where a function is written. */

const Row = ({ label, children, note }) => (
  <div className={s.row}>
    <span className={s.rowLabel}>{label}</span>
    {children}
    {note ? <p className={s.note}>{note}</p> : null}
  </div>
)

const Choice = ({ options, value, onPick, name }) => (
  <div className={s.choices} role="radiogroup" aria-label={name}>
    {options.map(option => (
      <button
        key={option.id}
        type="button"
        role="radio"
        aria-checked={value === option.id}
        className={`${s.choice} ${value === option.id ? s.choiceOn : ""}`}
        onClick={() => onPick(option.id)}
      >
        {option.label}
        {option.blurb ? <span className={s.choiceBlurb}>{option.blurb}</span> : null}
      </button>
    ))}
  </div>
)

const QrStudio = () => {
  const [state, setState] = React.useState(emptyQr)
  const [error, setError] = React.useState("")
  const [copied, setCopied] = React.useState(false)

  const holder = React.useRef(null)
  const instance = React.useRef(null)

  const set = patch => setState(current => ({ ...current, ...patch }))

  const destination = DESTINATIONS.find(d => d.id === state.kind) || DESTINATIONS[0]
  const problem = qrProblem(state)
  const encoded = encodeValue(state)

  /* The preview always draws something — an empty code would leave the style
     controls apparently broken — but what it draws when there is nothing to
     encode is this page's own address, which is at least true. */
  const preview = React.useMemo(
    () => (problem ? { ...state, value: "freecontractorservices.com", kind: "url" } : state),
    [state, problem]
  )

  React.useEffect(() => {
    let cancelled = false

    ;(async () => {
      const { default: QRCodeStyling } = await import("qr-code-styling")
      if (cancelled || !holder.current) return

      const options = qrOptions(preview)
      if (!instance.current) {
        instance.current = new QRCodeStyling(options)
      } else {
        instance.current.update(options)
      }

      holder.current.innerHTML = ""
      instance.current.append(holder.current)
    })()

    return () => {
      cancelled = true
    }
  }, [preview])

  /* Opening a saved code — FCS-075. */
  const { opened, openError } = useOpenSaved(saved => setState(saved))

  const download = () => {
    if (problem || !instance.current) return
    instance.current.download({ name: qrFilename(state), extension: state.format })
  }

  const copy = async () => {
    if (!encoded) return
    try {
      await navigator.clipboard.writeText(encoded)
      setCopied(true)
      setTimeout(() => setCopied(false), 1800)
    } catch {
      setError("Your browser would not let us copy that. Select it and copy by hand.")
    }
  }

  const pickLogo = async file => {
    setError("")
    try {
      // The same reader the website builder uses: it redraws through a canvas,
      // so a 6 MB photograph does not become a 6 MB data URL in the QR code.
      const dataUrl = await readImageFile(file, { maxEdge: 512 })
      set({ logo: dataUrl, level: "H" })
    } catch (err) {
      setError(err.message)
    }
  }

  return (
    <div className={s.studio}>
      {/* FCS-075. Spans the whole grid (FCS-086): as a bare child it took one
          cell and pushed the QR preview below the controls. */}
      <div className={s.saveRow}>
        {openError ? <p className={s.note}>{openError}</p> : null}
        <SaveToAccount kind="qr" data={state} opened={opened} suggestedName={state.label || ""} />
      </div>

      <div className={s.controls}>
        <Row label="What should it do?">
          <Choice
            name="Destination type"
            options={DESTINATIONS}
            value={state.kind}
            onPick={kind => set({ kind })}
          />
        </Row>

        <Row label={destination.label} note={destination.hint}>
          <input
            id="qr-value"
            className={s.input}
            value={state.value}
            inputMode={destination.inputMode}
            placeholder={destination.placeholder}
            maxLength={600}
            onChange={e => set({ value: e.target.value })}
          />
        </Row>

        <Row label="Pattern">
          <Choice
            name="Pattern"
            options={PATTERNS}
            value={state.pattern}
            onPick={pattern => set({ pattern })}
          />
        </Row>

        <Row label="Colour">
          <div className={s.colourRow}>
            {SWATCHES.map(hex => (
              <button
                key={hex}
                type="button"
                aria-label={`Use ${hex}`}
                aria-pressed={state.colour.toLowerCase() === hex}
                className={`${s.swatch} ${state.colour.toLowerCase() === hex ? s.swatchOn : ""}`}
                style={{ background: hex }}
                onClick={() => set({ colour: hex })}
              />
            ))}
            {/* A native colour input rather than a picker library: it is the
                one the person's own device already knows how to show them. */}
            <label className={s.custom}>
              <input
                type="color"
                value={state.colour}
                onChange={e => set({ colour: e.target.value })}
                aria-label="Choose another colour"
              />
              <span>Custom</span>
            </label>
          </div>
        </Row>

        <Row
          label="Background"
          note="A transparent background is a PNG or SVG; JPG cannot carry one."
        >
          <div className={s.colourRow}>
            {["#ffffff", "#f6f8fb", "#0d1726", "transparent"].map(hex => (
              <button
                key={hex}
                type="button"
                aria-label={hex === "transparent" ? "No background" : `Use ${hex}`}
                aria-pressed={state.background === hex}
                className={`${s.swatch} ${state.background === hex ? s.swatchOn : ""} ${
                  hex === "transparent" ? s.swatchNone : ""
                }`}
                style={hex === "transparent" ? undefined : { background: hex }}
                onClick={() => set({ background: hex })}
              />
            ))}
          </div>
        </Row>

        <Row label="Corners">
          <div className={s.pair}>
            <div>
              <span className={s.subLabel}>Outer</span>
              <Choice
                name="Corner square style"
                options={CORNER_SQUARES}
                value={state.cornerSquare}
                onPick={cornerSquare => set({ cornerSquare })}
              />
            </div>
            <div>
              <span className={s.subLabel}>Inner</span>
              <Choice
                name="Corner dot style"
                options={CORNER_DOTS}
                value={state.cornerDot}
                onPick={cornerDot => set({ cornerDot })}
              />
            </div>
          </div>
        </Row>

        <Row
          label="Logo"
          note="Yours only. It is punched out of the middle of the code, so keep error correction high."
        >
          <div className={s.logoRow}>
            {state.logo ? (
              <span className={s.logoThumb}>
                <img src={state.logo} alt="" />
                <button
                  type="button"
                  aria-label="Remove the logo"
                  onClick={() => set({ logo: null })}
                >
                  ×
                </button>
              </span>
            ) : null}
            <label className={s.fileBtn}>
              {state.logo ? "Replace" : "Add a logo"}
              <input
                type="file"
                accept="image/*"
                hidden
                onChange={e => {
                  const file = e.target.files && e.target.files[0]
                  if (file) pickLogo(file)
                  e.target.value = ""
                }}
              />
            </label>
          </div>
        </Row>

        <Row label="Error correction" note="How much of the code can be scuffed and still scan.">
          <Choice
            name="Error correction"
            options={LEVELS}
            value={state.level}
            onPick={level => set({ level })}
          />
        </Row>

        {error ? <p className={s.error}>{error}</p> : null}
      </div>

      <aside className={s.side}>
        <div className={s.previewCard}>
          {/* The chequerboard is only meaningful when the code HAS no
              background — behind a white one it just reads as noise. */}
          <div
            className={`${s.preview} ${state.background === "transparent" ? s.previewClear : ""}`}
            ref={holder}
            aria-hidden="true"
          />

          {problem ? (
            <p className={s.previewNote}>{problem}</p>
          ) : (
            <p className={s.previewCode} title={encoded}>
              {encoded}
            </p>
          )}

          <div className={s.formats} role="radiogroup" aria-label="File format">
            {FORMATS.map(format => (
              <button
                key={format.id}
                type="button"
                role="radio"
                aria-checked={state.format === format.id}
                className={`${s.format} ${state.format === format.id ? s.formatOn : ""}`}
                onClick={() => set({ format: format.id })}
              >
                {format.label}
              </button>
            ))}
          </div>

          <button
            type="button"
            className={`btn btn--lg ${s.download}`}
            disabled={Boolean(problem)}
            onClick={download}
          >
            Download
          </button>

          <button type="button" className={s.copy} disabled={!encoded} onClick={copy}>
            {copied ? "Copied" : "Copy the link"}
          </button>

          <p className={s.privacy}>
            Made in this tab. Nothing is uploaded, and a logo you add never leaves your browser.
          </p>
        </div>
      </aside>
    </div>
  )
}

export default QrStudio
