/**
 * Turning a picked file into something safe to keep in localStorage.
 *
 * A phone photograph is routinely 4–8 MB, and localStorage gives the whole
 * origin about 5 MB. Storing the raw file as a data URL would blow the quota
 * on the FIRST upload and take the rest of the draft down with it, so every
 * image is redrawn through a canvas at a sane size before it is ever stored.
 *
 * JPEG, not PNG: these are photographs of roofs and kitchens, and a PNG of a
 * photograph is several times larger for no visible gain. Transparency is not
 * something an image slot on a contractor site needs.
 */

const MAX_EDGE = 1600
const QUALITY = 0.82

/** Resolves to a data URL, or rejects with a message fit to show a person. */
export function readImageFile(file, { maxEdge = MAX_EDGE, quality = QUALITY } = {}) {
  return new Promise((resolve, reject) => {
    if (!file) {
      reject(new Error("No file chosen."))
      return
    }
    if (!file.type.startsWith("image/")) {
      reject(new Error("That is not an image file."))
      return
    }
    // A generous ceiling purely to fail fast on a 60 MB RAW before spending
    // time decoding it. The canvas pass is what actually controls the size.
    if (file.size > 25 * 1024 * 1024) {
      reject(new Error("That image is too large. Please choose one under 25 MB."))
      return
    }

    const url = URL.createObjectURL(file)
    const img = new Image()

    img.onload = () => {
      URL.revokeObjectURL(url)
      try {
        const scale = Math.min(1, maxEdge / Math.max(img.width, img.height))
        const w = Math.max(1, Math.round(img.width * scale))
        const h = Math.max(1, Math.round(img.height * scale))

        const canvas = document.createElement("canvas")
        canvas.width = w
        canvas.height = h
        const ctx = canvas.getContext("2d")
        // White beneath, so a transparent PNG does not flatten to black.
        ctx.fillStyle = "#ffffff"
        ctx.fillRect(0, 0, w, h)
        ctx.drawImage(img, 0, 0, w, h)

        resolve(canvas.toDataURL("image/jpeg", quality))
      } catch {
        reject(new Error("That image could not be processed."))
      }
    }

    img.onerror = () => {
      URL.revokeObjectURL(url)
      reject(new Error("That image could not be read."))
    }

    img.src = url
  })
}
