import * as React from "react"
import Header from "../components/Header"
import Seo from "../components/Seo"
import QrStudio from "../components/qr/QrStudio"
import * as s from "../components/qr/QrPage.module.css"

/**
 * Free QR codes — MTC-FCS-020.
 * ============================================================================
 * The third of the three free services the landing page promises, and the
 * only one that was already written: this is the qrcode-king prototype's
 * generator, ported and stripped of everything to do with analytics,
 * campaigns and saved codes.
 *
 * ── NO SIGN-UP, BECAUSE THE CARD SAYS SO ───────────────────────────────────
 * "No sign-up required" is printed on the landing page. The whole thing runs
 * in the tab, so there is nothing to sign in to and nothing to charge for.
 */
const QrPage = () => (
  <>
    <Header />
    <main className={s.page} data-print="hide">
      <div className={`container ${s.wide}`}>
        <div className={s.head}>
          <h1 className={s.title}>Free QR codes</h1>
          <p className={s.lead}>
            Make a code for your website, your phone number or anything else, style it to match
            your business, and download it. No account, nothing to pay, and as many as you like.
          </p>
        </div>

        <QrStudio />

        <div className={s.tips}>
          <h2 className={s.tipsTitle}>Printing it</h2>
          <ul className={s.tipsList}>
            <li>
              <strong>Download the SVG for anything printed.</strong> It stays sharp at any size,
              which a PNG blown up to fill a van door does not.
            </li>
            <li>
              <strong>Leave white space around it.</strong> Scanners need a clear border; a code
              printed hard against a graphic often will not read.
            </li>
            <li>
              <strong>Keep it above about an inch.</strong> A phone needs roughly ten times the
              code's width in distance to focus, so a small code is a close-up code.
            </li>
            <li>
              <strong>Test it before it goes to the printer.</strong> Scan the downloaded file with
              your own phone — not the preview on this page.
            </li>
          </ul>
        </div>
      </div>
    </main>
  </>
)

export const Head = () => (
  <Seo
    title="Free QR code generator"
    description="Make QR codes for your website, phone number or contact details. Style them to match your business and download them free — no account needed."
    path="/qr-codes/"
  />
)

export default QrPage
